/** Dispatch places a window booking's exact hour (same promised day only). */
function SetSlotForm({ booking }: { booking: AdminBooking }) {
  const mut = useBookingMutation();
  const inWindow = (slot: string) =>
    booking.flex_window === "afternoon" ? slot >= "12:00" : slot < "12:00";
  const [time, setTime] = useState(() =>
    inWindow(booking.preferred_time.slice(0, 5))
      ? booking.preferred_time.slice(0, 5)
      : booking.flex_window === "afternoon" ? "12:00" : "08:00",
  );
  const [failed, setFailed] = useState<string | null>(null);
  return (
    <div className="mt-2 flex flex-col gap-2">
      <div>
        <Label htmlFor={`setslot-time-${booking.id}`}>Exact hour</Label>
        <div className="mt-1 flex gap-2">
          <select
            id={`setslot-time-${booking.id}`}
            value={time}
            onChange={(e) => setTime(e.target.value)}
            className="min-h-[44px] flex-1 cursor-pointer rounded-lg border border-gray-200 bg-white px-3 py-2 font-technical text-sm text-gray-900 focus:border-primary-600 focus:outline-none"
          >
            {TIME_SLOTS.filter(inWindow).map((slot) => (
              <option key={slot} value={slot}>
                {formatTime12h(slot)}
              </option>
            ))}
          </select>
          <Button
            size="sm"
            disabled={mut.setSlot.isPending}
            onClick={() => {
              setFailed(null);
              mut.setSlot.mutate(
                { id: booking.id, date: booking.preferred_date, time },
                {
                  onSuccess: () =>
                    toast.success("Time set", "Customer emailed the exact hour."),
                  onError: (e) =>
                    setFailed(e instanceof Error ? e.message : "Could not set the time."),
                },
              );
            }}
          >
            {mut.setSlot.isPending ? "Setting…" : "Set time"}
          </Button>
        </div>
      </div>
      {failed && (
        <p role="alert" className="text-sm text-error-600">{failed}</p>
      )}
      <p className="text-xs text-gray-500">
        Inside the promised {booking.flex_window === "afternoon" ? "afternoon" : "morning"} only — the server enforces it.
      </p>
    </div>
  );
}

function Body({ booking, onClose, startAssignOpen = false }: { booking: AdminBooking; onClose: () => void; startAssignOpen?: boolean }) {
  const user = useAuthStore((s) => s.user);
  const mut = useBookingMutation();
  const [assignOpen, setAssignOpen] = useState(startAssignOpen);
  const [confirm, setConfirm] = useState<ConfirmSpec | null>(null);
  const canVerify = user?.role === "owner" || !!user?.can_execute_refunds;
  const payment = booking.payment ?? null;
  const name = `${booking.customer_first_name} ${booking.customer_last_name}`.trim();
  const cancellable = ["submitted", "pending", "confirmed", "rescheduled", "ongoing"].includes(booking.status);

  return (
    <>
      <div className="flex flex-col gap-4">
        <Block title="Customer">
          <dl>
            <DetailRow label="Name" value={name} />
            <DetailRow label="Phone" value={booking.customer_phone} />
            <DetailRow label="Email" value={booking.customer_email} />
          </dl>
        </Block>

        <Block title="Address">
          <dl>
            <DetailRow label="Area" value={booking.address_text ?? "—"} />
            <DetailRow label="Landmark" value={booking.landmark ?? "—"} />
          </dl>
        </Block>

        <Block title="Service & schedule">
          <dl>
            <DetailRow
              label="Service"
              value={[booking.service_name ?? `Service #${booking.service_id}`, booking.brand_name ?? `Brand #${booking.brand_id}`].join(" · ")}
            />
            <DetailRow
              label="Price"
              value={`${formatPeso(booking.down_payment_amount)} down${booking.total_service_cost != null ? ` · ${formatPeso(booking.total_service_cost)} total` : ""}`}
            />
            <DetailRow
              label="Schedule"
              value={`${formatDateLong(booking.preferred_date)} · ${formatTimeRange(booking.preferred_time, booking.service_estimated_duration_minutes)}`}
            />
            {booking.flex_window && (
              <DetailRow
                label="Window"
                value={booking.flex_window === "morning" ? "Morning (arrive 8–12)" : "Afternoon (arrive 12–4)"}
              />
            )}
            {booking.flex_window && <SetSlotForm booking={booking} />}
            {booking.status === "submitted" && booking.expires_at && (
              <DetailRow label="Pay before" value={formatDateLong(booking.expires_at)} />
            )}

# Request Mocking

Intercept, mock, modify, and block network requests.

## CLI Route Commands

```bash
# Mock with custom status
playwright-cli route "**/*.jpg" --status=404

# Mock with JSON body
playwright-cli route "**/api/users" --body='[{"id":1,"name":"Alice"}]' --content-type=application/json

# Mock with custom headers
playwright-cli route "**/api/data" --body='{"ok":true}' --header="X-Custom: value"

# Remove headers from requests
playwright-cli route "**/*" --remove-header=cookie,authorization

# List active routes
playwright-cli route-list

# Remove a route or all routes
playwright-cli unroute "**/*.jpg"
playwright-cli unroute
```

## URL Patterns

```
**/api/users           - Exact path match
**/api/*/details       - Wildcard in path
**/*.{png,jpg,jpeg}    - Match file extensions
**/search?q=*          - Match query parameters
```

## Advanced Mocking with run-code

For conditional responses, request body inspection, response modification, or delays:

### Conditional Response Based on Request

```bash
playwright-cli run-code "async page => {
  await page.route('**/api/login', route => {
    const body = route.request().postDataJSON();
    if (body.username === 'admin') {
      route.fulfill({ body: JSON.stringify({ token: 'mock-token' }) });
    } else {
      route.fulfill({ status: 401, body: JSON.stringify({ error: 'Invalid' }) });
    }
  });
}"
```

### Modify Real Response

```bash
playwright-cli run-code "async page => {
  await page.route('**/api/user', async route => {
    const response = await route.fetch();
    const json = await response.json();
    json.isPremium = true;
    await route.fulfill({ response, json });
  });
}"
```

### Simulate Network Failures

```bash
playwright-cli run-code "async page => {
  await page.route('**/api/offline', route => route.abort('internetdisconnected'));
}"
# Options: connectionrefused, timedout, connectionreset, internetdisconnected
```

### Delayed Response

```bash
playwright-cli run-code "async page => {
  await page.route('**/api/slow', async route => {
    await new Promise(r => setTimeout(r, 3000));
    route.fulfill({ body: JSON.stringify({ data: 'loaded' }) });
  });
}"
```

