                 confirmLabel: "Log out",
                 destructive: true,
                 icon: <LogOut size={20} aria-hidden="true" className="shrink-0 text-error-500" />,
                 onConfirm: goSignOut,
               }
             : null
         }
         onClose={() => setConfirmOut(false)}
       />
