         </header>
         <ScrollArea className="min-h-0 flex-1" viewportId="office-scroll">
           <main className="scroll-mt-4 overflow-x-clip p-4 contain-inline-size sm:p-6" id="admin-content">{children}</main>
         </ScrollArea>
       </div>
       <Toaster />
     </div>
   );
 }

