/** 5-step progressive booking form with autosave draft. */
export function BookingForm() {
  const navigate = useNavigate();
  const { data: content } = useLandingContent();
  const create = useCreateBooking();
  const [serverErrors, setServerErrors] = useState<string[]>([]);
  // Seat hold for the picked slot (never drafted, never submitted stale:
  // only sent when it still matches the current pick).
  const [hold, setHold] = useState<SlotHoldState | null>(null);
  // Windows-first: exact hours stay behind the toggle. Anchor pins the
  // stored time while a window is picked (backend contract keeps HH:MM).
  const [schedMode, setSchedMode] = useState<ScheduleMode>("window");
  const [flexWindow, setFlexWindow] = useState<FlexWindow>("morning");

  const form = useForm<BookingFormValues>({
    resolver: zodResolver(bookingSchema),
    defaultValues: useMemo(loadDraft, []),
    mode: "onBlur",
  });
  const { register, handleSubmit, watch, setValue, setError, formState } = form;
  const errors = formState.errors;
  const pickedDate = watch("preferred_date");

  // Window mode pins the stored hour to the window anchor.
  useEffect(() => {
    if (schedMode === "window" && pickedDate) {
      const anchor = windowAnchor(flexWindow);
      if (watch("preferred_time") !== anchor) {
        setValue("preferred_time", anchor, { shouldValidate: true });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [schedMode, flexWindow, pickedDate]);

  // Autosave draft (never the agreements).
  const watched = watch();
  useEffect(() => {
    const t = window.setTimeout(() => {
      const { agree_payment: _p, agree_terms: _t, ...rest } = watched;
      try {
        localStorage.setItem(DRAFT_KEY, JSON.stringify(rest));
      } catch {
        /* storage full — non-fatal */
      }
    }, 600);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [JSON.stringify({ ...watched, agree_payment: undefined, agree_terms: undefined })]);

  useEffect(() => {
    try {
      if (localStorage.getItem(DRAFT_KEY)) {
        toast.info("Draft restored", "Your unfinished booking was restored.");
      }
    } catch {
      /* ignore */
    }
  }, []);

  const onSubmit = handleSubmit(
    (values) => {
    setServerErrors([]);
    const { agree_payment: _p, agree_terms: _t, ...payload } = values;
    const liveHold =
      schedMode === "exact" &&
      hold !== null &&
      hold.date === values.preferred_date &&
      hold.time === values.preferred_time
        ? hold.token
        : null;
    create.mutate(
      {
        ...payload,
        service_id: Number(payload.service_id),
        brand_id: Number(payload.brand_id),
        problem_description: payload.problem_description?.trim() || null,
        turnstile_token: null, // documented dev bypass (no site key on staging)
        hold_token: liveHold,
        flex_window: schedMode === "window" ? flexWindow : null,
      },

