import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { FieldError, Input, Label } from "@/components/ui/input";
import { useJoinWaitlist } from "@/hooks/usePublic";
import { REFERENCE_RE } from "@/types/booking.types";

void REFERENCE_RE;

const waitlistSchema = z.object({
  preferred_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "Pick a day"),
  name: z.string().trim().min(1, "Enter your name").max(200),
  phone: z
    .string()
    .trim()
    .regex(/^(09|\+639)\d{9}$/, "Use 09XXXXXXXXX or +639XXXXXXXXX"),
  email: z.string().trim().email("Enter a valid email address").max(320),
});

type WaitlistValues = z.infer<typeof waitlistSchema>;

/** Full day? Guests join the line here — the offer arrives by email. */
export function WaitlistJoin() {
  const join = useJoinWaitlist();
  const [done, setDone] = useState<string | null>(null);
  const { register, handleSubmit, formState } = useForm<WaitlistValues>({
    resolver: zodResolver(waitlistSchema),
    mode: "onBlur",
  });
  const errors = formState.errors;

  return (
    <div className="mt-4 rounded-lg border border-gray-200 bg-white p-4">
      <h3 className="text-sm font-semibold text-gray-900">Day full? Join the waitlist</h3>
      <p className="mt-0.5 text-xs text-gray-500">
        Pick the full day — if a seat opens, we email you a booking link.
      </p>
      {done ? (
        <p className="mt-3 text-sm font-medium text-teal-700" role="status">{done}</p>
      ) : (
        <form
          className="mt-3 flex flex-col gap-2.5"
          noValidate
          onSubmit={handleSubmit((values) =>
            join.mutate(values, {
              onSuccess: () => {
                setDone(`You're on the list for ${values.preferred_date} — check ${values.email}.`);
              },
            }),
          )}
        >
          <div>
            <Label htmlFor="wl-date">Day *</Label>
            <Input id="wl-date" type="date" {...register("preferred_date")} />
            <FieldError message={errors.preferred_date?.message} />
          </div>
          <div className="grid grid-cols-1 gap-2.5 sm:grid-cols-2">
            <div>
              <Label htmlFor="wl-name">Name *</Label>
              <Input id="wl-name" placeholder="Juan Cruz" autoComplete="name" {...register("name")} />
              <FieldError message={errors.name?.message} />
            </div>
            <div>
              <Label htmlFor="wl-phone">Contact number *</Label>
              <Input id="wl-phone" placeholder="09XX-XXX-XXXX" autoComplete="tel" {...register("phone")} />
              <FieldError message={errors.phone?.message} />
            </div>
          </div>
          <div>
            <Label htmlFor="wl-email">Email *</Label>
            <Input id="wl-email" type="email" placeholder="you@email.com" autoComplete="email" {...register("email")} />
            <FieldError message={errors.email?.message} />
          </div>
          {join.isError && (
            <p className="text-sm text-error-600" role="alert">
              {join.error instanceof Error ? join.error.message : "Could not join the waitlist."}
            </p>
          )}
          <Button type="submit" disabled={join.isPending} className="w-full sm:w-auto">
            {join.isPending ? "Joining…" : "Join waitlist"}
          </Button>
        </form>
      )}
    </div>
  );
}

