async page => {
  const TIMES = ["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00"];
  const isoOf = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const vacancy = (from, to) => {
    const days = [];
    const start = new Date(from + "T00:00:00");
    const end = new Date(to + "T00:00:00");
    let n = 0;
    for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1), n += 1) {
      const date = isoOf(d);
      const sunday = d.getDay() === 0;
      const slots = TIMES.map((t, i) => {
        if (sunday) return { time: t, state: "closed", capacity: 3, booked: 0, holds: 0, left: 0 };
        const k = (n + i) % 5;
        if (k === 0) return { time: t, state: "full", capacity: 3, booked: 3, holds: 0, left: 0 };
        if (k === 1) return { time: t, state: "low", capacity: 3, booked: 2, holds: 0, left: 1 };
        return { time: t, state: "open", capacity: 3, booked: 1, holds: 0, left: 2 };
      });
      days.push({ date, slots });
    }
    return { days };
  };
  const bookings = [
    {
      id: 101, reference_id: "KJAC-2026-A1B2C3", status: "confirmed",
      customer_first_name: "Ana", customer_last_name: "Reyes",
      customer_email: "ana@example.com", customer_phone: "09170001111",
      service_id: 1, brand_id: 1, service_name: "General Cleaning", brand_name: "Daikin",
      service_estimated_duration_minutes: 90,
      preferred_date: "2026-09-16", preferred_time: "09:00:00",
      down_payment_amount: 500, total_service_cost: 1500, expires_at: null,
      technician_id: 301, technician: { id: 301, name: "Marco Santos" }, flex_window: null,
      address_text: "QC", landmark: "Church", payment: null,
      active_reschedule: null, timeline: [], created_at: null, updated_at: null
    },
    {
      id: 102, reference_id: "KJAC-2026-D4E5F6", status: "pending",
      customer_first_name: "Ben", customer_last_name: "Cruz",
      customer_email: "ben@example.com", customer_phone: "09170002222",
      service_id: 1, brand_id: 2, service_name: "General Cleaning", brand_name: "Samsung",
      service_estimated_duration_minutes: 90,
      preferred_date: "2026-09-16", preferred_time: "08:00:00",
      down_payment_amount: 500, total_service_cost: 1500, expires_at: null,
      technician_id: null, technician: null, flex_window: "morning",
      address_text: "Pasig", landmark: "Gate", payment: null,
      active_reschedule: null, timeline: [], created_at: null, updated_at: null
    }
  ];
  let waitlist = [
    { id: 1, preferred_date: "2026-09-16", name: "Wally List", phone: "09171234567", email: "wally@example.com", status: "waiting" },
    { id: 2, preferred_date: "2026-09-16", name: "Zed Zane", phone: "09177654321", email: "zed@example.com", status: "waiting" }
  ];
  const settings = [
    { setting_key: "reminder_booking_tomorrow_enabled", setting_value: "true", data_type: "boolean" },
    { setting_key: "reminder_payment_expiring_enabled", setting_value: "true", data_type: "boolean" }
  ];
  const q = url => {
    const m = url.match(/[?&]([^=&#]+)=([^&#]*)/g) || [];
    const o = {};
    m.forEach(p => {
      const kv = p.substring(1).split("=");
      o[decodeURIComponent(kv[0])] = decodeURIComponent(kv[1] || "");
    });
    return o;
  };
  const json = body => ({ status: 200, contentType: "application/json", body: JSON.stringify(body) });
  await page.route("**/v1/admin/slots/vacancy?*", async route => {
    const p = q(route.request().url());
    await route.fulfill(json(vacancy(p.date_from, p.date_to)));
  });
  await page.route("**/v1/admin/bookings?*", async route => {
    await route.fulfill(json({ total: bookings.length, items: bookings, summary: {} }));
  });
  await page.route("**/v1/admin/waitlist?*", async route => {
    await route.fulfill(json(waitlist));
  });
  await page.route("**/v1/admin/waitlist/*/offer", async route => {
    const m = route.request().url().match(/\/admin\/waitlist\/(\d+)\/offer/);
    const entry = waitlist.find(w => w.id === Number(m[1]));
    entry.status = "offered";
    await route.fulfill(json({
      entry,
      booking_link: "http://localhost:5173/book?hold=tok&date=2026-09-16&time=09:00",
      hold_expires_at: new Date(Date.now() + 86400000).toISOString()
    }));
  });
  await page.route("**/v1/admin/waitlist/*/remove", async route => {
    const m = route.request().url().match(/\/admin\/waitlist\/(\d+)\/remove/);
    const entry = waitlist.find(w => w.id === Number(m[1]));
    entry.status = "removed";
    waitlist = waitlist.filter(w => w.id !== entry.id);
    await route.fulfill(json(entry));
  });
  await page.route("**/v1/admin/settings", async route => {
    await route.fulfill(json(settings));
  });
  await page.route("**/v1/admin/settings/*", async route => {
    const m = route.request().url().match(/\/admin\/settings\/([^/?]+)/);
    const posted = route.request().postDataJSON();
    const row = settings.find(s => s.setting_key === m[1]);
    row.setting_value = posted.setting_value;
    await route.fulfill(json(row));
  });
  await page.route("**/v1/admin/reminders/run", async route => {
    await route.fulfill(json({ tomorrow_sent: 2, payment_sent: 1 }));
  });
  return "schedule mocks installed";
}

