@@ -1,536 +1,539 @@
 import { useMemo, useState } from "react";
 import { BellRing, CalendarDays, ChevronLeft, ChevronRight, Megaphone, Trash2 } from "lucide-react";
 import { Block } from "@/components/office/BookingDetailSheet";
 import { ErrorCard, PageHeader } from "@/components/shared/PageHeader";
 import { StatCard } from "@/components/shared/StatCard";
 import { StatusBadge } from "@/components/shared/StatusBadge";
 import { Button } from "@/components/ui/button";
 import { CardSkeleton } from "@/components/ui/skeleton";
 import { Sheet, SheetCloseButton, SheetContent, SheetTitle } from "@/components/ui/sheet";
 import { TIME_SLOTS, windowSlots } from "@/components/forms/SchedulePicker";
 import { useAdminBookings } from "@/hooks/useOffice";
 import {
   useAdminSettings,
   usePatchSetting,
   useReminderRun,
   useVacancy,
   useWaitlist,
   useWaitlistMutation,
 } from "@/hooks/useOffice";
 import { useAuthStore } from "@/stores/auth.store";
 import { toast } from "@/stores/toast.store";
 import type { VacancyDay, VacancySlot, WaitlistEntry } from "@/types/booking.types";
 import { formatDateLong, formatTime12h } from "@/utils/format";
 import { cn } from "@/lib/utils";

 function parseISO(ymd: string): Date {
   const [y, m, d] = ymd.split("-").map(Number);
   return new Date(y, m - 1, d);
 }

 function toISO(d: Date): string {
   return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
 }

 function addDaysISO(ymd: string, n: number): string {
   const d = parseISO(ymd);
   d.setDate(d.getDate() + n);
   return toISO(d);
 }

 function mondayOf(ymd: string): string {
   const d = parseISO(ymd);
   const shift = (d.getDay() + 6) % 7; // Monday start
   d.setDate(d.getDate() - shift);
   return toISO(d);
 }

 function manilaToday(): string {
   const parts = new Intl.DateTimeFormat("en-CA", {
     timeZone: "Asia/Manila",
     year: "numeric",
     month: "2-digit",
     day: "2-digit",
   }).formatToParts(new Date());
   const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
   return `${get("year")}-${get("month")}-${get("day")}`;
 }

 const WEEKDAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

 function dayLabel(ymd: string): { wd: string; num: string } {
   const d = parseISO(ymd);
   return { wd: WEEKDAYS[(d.getDay() + 6) % 7], num: String(d.getDate()) };
 }

 function monthTitle(weekStart: string): string {
   const first = parseISO(weekStart);
   const last = parseISO(addDaysISO(weekStart, 6));
   const long = (d: Date) => d.toLocaleDateString("en-US", { month: "long", year: "numeric" });
   if (first.getMonth() === last.getMonth()) return long(first);
   const short = (d: Date) => d.toLocaleDateString("en-US", { month: "short" });
   return `${short(first)} – ${short(last)} ${last.getFullYear()}`;
 }

 /** A day the server drops (past days) reads Closed: unbookable either way. */
 function closedDay(date: string): VacancyDay {
   return {
     date,
     slots: TIME_SLOTS.map((time) => ({
       time, state: "closed", capacity: 0, booked: 0, holds: 0, left: 0,
     })),
   };
 }

 /** Slot state → cell paint (meaning board: teal live · amber filling · slate full). */
 function cellPaint(state: VacancySlot["state"]): string {
   switch (state) {
     case "open":
       return "border-teal-200 bg-teal-50 text-teal-900 hover:bg-teal-100";
     case "low":
       return "border-warning-200 bg-warning-50 text-warning-800 hover:bg-warning-100";
     case "full":
       return "border-slate-200 bg-slate-100 text-slate-600 hover:bg-slate-200";
     default:
       return "border-gray-100 bg-gray-50 text-gray-400";
   }
 }

 function cellText(slot: VacancySlot): string {
   switch (slot.state) {
     case "open":
       return slot.left === 1 ? "1 free" : `${slot.left} free`;
     case "low":
       return slot.left === 1 ? "Last seat" : `${slot.left} left`;
     case "full":
       return "Full";
     default:
       return "Closed";
   }
 }

 interface SlotSel {
   date: string;
   time: string;
 }

 /** Slot drawer: who is in this hour + the day's waitlist with offer/remove. */
 function SlotDrawer({ sel, onClose }: { sel: SlotSel | null; onClose: () => void }) {
   const day = sel?.date ?? null;
   const board = useAdminBookings({ date_from: day ?? undefined, date_to: day ?? undefined, limit: 100 });
   const waitlist = useWaitlist(day);
   const wl = useWaitlistMutation();

   const rows = useMemo(() => {
     if (!sel) return [];
     const items = board.data?.items ?? [];
     // Mirror the server count: window bookings sit in every slot of
     // their window until dispatch places the exact hour.
     return items.filter((b) => {
       const t = b.preferred_time.slice(0, 5);
       if (t === sel.time) return true;
       if (b.flex_window === "morning") return windowSlots("morning").includes(sel.time);
       if (b.flex_window === "afternoon") return windowSlots("afternoon").includes(sel.time);
       return false;
     });
   }, [board.data, sel]);

   const offer = (entry: WaitlistEntry) => {
     if (!sel) return;
     wl.offer.mutate(
       { id: entry.id, time: sel.time },
       {
         onSuccess: () => toast.success("Offer sent", `${entry.name} was emailed a booking link.`),
         onError: (e) => toast.error("Offer failed", e instanceof Error ? e.message : undefined),
       },
     );
   };

   return (
     <Sheet open={sel !== null} onOpenChange={(open) => { if (!open) onClose(); }}>
       <SheetContent
         className="flex w-full flex-col gap-0 p-0 sm:max-w-md"
         label={sel ? `Slot ${sel.date} ${sel.time}` : "Slot details"}
         onClose={onClose}
       >
         <div className="flex items-start justify-between gap-2 border-b border-gray-200 p-4">
           <div>
             <SheetTitle>{sel ? formatDateLong(sel.date) : ""}</SheetTitle>
             <p className="mt-0.5 text-sm tabular-nums text-gray-600">
               {sel ? `${formatTime12h(sel.time)} hour` : ""}
             </p>
           </div>
           <SheetCloseButton onClose={onClose} />
         </div>
         <div className="thin-scroll flex-1 overflow-y-auto p-4">
           <div className="flex flex-col gap-4">
             <Block title={`Bookings (${rows.length})`}>
               {board.isPending ? (
                 <p className="text-sm text-gray-500">Loading…</p>
               ) : rows.length === 0 ? (
                 <p className="text-sm text-gray-500">Nobody in this hour yet.</p>
               ) : (
                 <dl className="flex flex-col gap-2">
                   {rows.map((b) => (
                     <div key={b.id} className="flex items-center justify-between gap-2 rounded-lg border border-gray-100 px-2.5 py-2">
                       <div className="min-w-0">
                         <p className="truncate text-sm font-semibold text-gray-900">
                           {`${b.customer_first_name} ${b.customer_last_name}`.trim()}
                         </p>
                         <p className="truncate font-technical text-xs text-gray-500">{b.reference_id}</p>
                       </div>
                       <StatusBadge status={b.status} />
                     </div>
                   ))}
                 </dl>
               )}
             </Block>
             <Block title={`Waitlist (${(waitlist.data ?? []).length})`}>
               {waitlist.isPending ? (
                 <p className="text-sm text-gray-500">Loading…</p>
               ) : (waitlist.data ?? []).length === 0 ? (
                 <p className="text-sm text-gray-500">Nobody waiting on this day.</p>
               ) : (
                 <dl className="flex flex-col gap-2">
                   {(waitlist.data ?? []).map((entry) => (
                     <div key={entry.id} className="flex items-center justify-between gap-2 rounded-lg border border-gray-100 px-2.5 py-2">
                       <div className="min-w-0">
                         <p className="truncate text-sm font-semibold text-gray-900">{entry.name}</p>
                         <p className="truncate text-xs tabular-nums text-gray-500">{entry.phone}</p>
                         {entry.status === "offered" && (
                           <p className="text-xs font-medium text-teal-700">Offered — link emailed</p>
                         )}
                       </div>
                       <div className="flex shrink-0 gap-1.5">
                         {entry.status === "waiting" && (
                           <Button
                             type="button"
                             size="sm"
                             disabled={wl.offer.isPending}
                             onClick={() => offer(entry)}
                           >
                             <Megaphone size={14} aria-hidden="true" />
                             Offer
                           </Button>
                         )}
                         <Button
                           type="button"
                           size="sm"
                           variant="outline"
                           aria-label={`Remove ${entry.name} from waitlist`}
                           disabled={wl.remove.isPending}
                           onClick={() =>
                             wl.remove.mutate(entry.id, {
                               onError: (e) => toast.error("Remove failed", e instanceof Error ? e.message : undefined),
                             })
                           }
                         >
                           <Trash2 size={14} aria-hidden="true" />
                         </Button>
                       </div>
                     </div>
                   ))}
                 </dl>
               )}
             </Block>
           </div>
         </div>
       </SheetContent>
     </Sheet>
   );
 }

 const REMINDER_KEYS = [
   { key: "reminder_booking_tomorrow_enabled", label: "Booking tomorrow", hint: "Nudge guests the evening before (5 PM)." },
   { key: "reminder_payment_expiring_enabled", label: "Payment expiring", hint: "Nudge unpaid guests with 2 hours left." },
 ] as const;

 /** Owner-only: reminder toggles + manual send. Staff never sees this card. */
 function RemindersCard() {
   const user = useAuthStore((s) => s.user);
   const isOwner = user?.role === "owner";
   const settings = useAdminSettings(isOwner);
   const patch = usePatchSetting();
   const run = useReminderRun();
   const [lastRun, setLastRun] = useState<string | null>(null);

   if (!isOwner) return null;

   const valueOf = (key: string) =>
     settings.data?.find((s) => s.setting_key === key)?.setting_value !== "false";

   const flip = (key: string, on: boolean) => {
     patch.mutate(
       { key, value: on ? "true" : "false" },
       {
         onSuccess: () => toast.success(on ? "Reminder on" : "Reminder off"),
         onError: (e) => toast.error("Save failed", e instanceof Error ? e.message : undefined),
       },
     );
   };

   return (
     <section aria-label="Reminders" className="mt-6 rounded-lg border border-gray-200 bg-white p-4">
       <div className="flex flex-wrap items-center justify-between gap-2">
         <div className="flex items-center gap-2">
           <BellRing size={18} aria-hidden="true" className="text-gray-500" />
           <h2 className="text-base font-semibold text-gray-900">Reminders</h2>
         </div>
         <Button
           type="button"
           size="sm"
           variant="outline"
           disabled={run.isPending}
           onClick={() =>
             run.mutate(undefined, {
               onSuccess: (r) => {
                 setLastRun(`Sent ${r.tomorrow_sent} booking, ${r.payment_sent} payment.`);
                 toast.success("Reminders sent", `Booking: ${r.tomorrow_sent} · Payment: ${r.payment_sent}.`);
               },
               onError: (e) => toast.error("Send failed", e instanceof Error ? e.message : undefined),
             })
           }
         >
           {run.isPending ? "Sending…" : "Send now"}
         </Button>
       </div>
       {settings.isPending ? (
         <p className="mt-3 text-sm text-gray-500">Loading…</p>
       ) : settings.isError ? (
         <ErrorCard message="Could not load reminder settings." onRetry={() => void settings.refetch()} />
       ) : (
         <ul className="mt-3 flex flex-col gap-2">
           {REMINDER_KEYS.map(({ key, label, hint }) => {
             const on = valueOf(key);
             return (
               <li key={key}>
                 <label className="flex min-h-[44px] cursor-pointer items-center justify-between gap-3 rounded-lg border border-gray-100 px-3 py-2">
                   <span>
                     <span className="block text-sm font-medium text-gray-900">{label}</span>
                     <span className="block text-xs text-gray-500">{hint}</span>
                   </span>
                   <input
                     type="checkbox"
                     className="h-4 w-4 accent-primary-600"
                     checked={on}
                     disabled={patch.isPending}
                     onChange={(e) => flip(key, e.target.checked)}
                     aria-label={label}
                   />
                 </label>
               </li>
             );
           })}
         </ul>
       )}
       {lastRun && (
         <p className="mt-2 text-sm tabular-nums text-gray-600" role="status">{lastRun}</p>
       )}
       <p className="mt-2 text-xs text-gray-500">
         Automatic sending runs on a schedule — Send now is the manual pass.
       </p>
     </section>
   );
 }

 /** Dispatch vacancy grid: one week of slots, room at a glance. */
 export function SchedulePage() {
   const today = manilaToday();
   const [weekStart, setWeekStart] = useState(() => mondayOf(today));
   const [sunFirst, setSunFirst] = useState(false);
   const [sel, setSel] = useState<SlotSel | null>(null);

   // Sunday-first weeks anchor a day earlier, so the column always holds
   // the true Sunday of the displayed week (never next Sunday).
   const viewStart = sunFirst ? addDaysISO(weekStart, -1) : weekStart;
   const viewEnd = addDaysISO(viewStart, 6);
   const vacancy = useVacancy(viewStart, viewEnd);

   const serverDays: VacancyDay[] = vacancy.data?.days ?? [];
   // Always seven columns; days the server drops (past days) render Closed.
   const week: VacancyDay[] = useMemo(() => {
     const out: VacancyDay[] = [];
     for (let offset = 0; offset < 7; offset += 1) {
       const date = addDaysISO(viewStart, offset);
       out.push(serverDays.find((d) => d.date === date) ?? closedDay(date));
     }
     return out;
   }, [viewStart, serverDays]);

   const days = week;

   const counts = useMemo(() => {
     let free = 0;
     let filling = 0;
     let full = 0;
     for (const d of days) {
       const states = d.slots.map((s) => s.state);
       if (states.includes("open")) free += 1;
       else if (states.includes("low")) filling += 1;
       else full += 1;
     }
     return { free, filling, full };
   }, [days]);

   const shiftWeek = (n: number) => {
     const next = addDaysISO(weekStart, n * 7);
     setWeekStart(next < mondayOf(today) ? mondayOf(today) : next);
   };

   return (
     <div className="min-w-0 overflow-x-clip">
       <PageHeader title="Schedule" description="Vacancy grid — room at a glance." />
       <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
         <StatCard title="Days with room" value={String(counts.free)} icon={CalendarDays} hint="At least one open slot" tint="teal" />
         <StatCard title="Filling days" value={String(counts.filling)} icon={CalendarDays} hint="Down to the last seats" tint="warning" />
         <StatCard title="Full days" value={String(counts.full)} icon={CalendarDays} hint="Nothing left to sell" tint="slate" />
       </div>

       <div className="mt-6 flex flex-wrap items-center justify-between gap-2">
         <div className="flex items-center gap-1.5">
           <Button
             type="button"
             variant="outline"
             size="sm"
+            className="border-gray-200 bg-white text-gray-700 hover:bg-gray-50"
             onClick={() => setWeekStart(mondayOf(today))}
           >
             Today
           </Button>
           <Button
             type="button"
             variant="outline"
             size="icon"
+            className="min-h-[36px] min-w-[36px] border-gray-200 bg-white text-gray-700 hover:bg-gray-50"
             disabled={weekStart <= mondayOf(today) || vacancy.isFetching}
             onClick={() => shiftWeek(-1)}
             aria-label="Previous week"
           >
             <ChevronLeft size={16} aria-hidden="true" />
           </Button>
           <Button
             type="button"
             variant="outline"
             size="icon"
+            className="min-h-[36px] min-w-[36px] border-gray-200 bg-white text-gray-700 hover:bg-gray-50"
             disabled={vacancy.isFetching}
             onClick={() => shiftWeek(1)}
             aria-label="Next week"
           >
             <ChevronRight size={16} aria-hidden="true" />
           </Button>
           <h2 className="ml-1 text-lg font-semibold text-gray-900">{monthTitle(viewStart)}</h2>
         </div>
         <div
           role="group"
           aria-label="Week order"
           className="flex overflow-hidden rounded-lg border border-gray-200 text-xs font-semibold"
         >
           {(
             [
               { sun: false, label: "Mon–Sun" },
               { sun: true, label: "Sun–Sat" },
             ] as const
           ).map(({ sun, label }) => (
             <button
               key={label}
               type="button"
               aria-pressed={sunFirst === sun}
               onClick={() => setSunFirst(sun)}
               className={cn(
                 "min-h-[36px] cursor-pointer px-3 transition-colors",
                 sunFirst === sun ? "bg-primary-700 text-white" : "bg-white text-gray-600 hover:bg-gray-50",
               )}
             >
               {label}
             </button>
           ))}
         </div>
       </div>

       <div className="mt-3 flex min-w-0 flex-col gap-3">
         {vacancy.isPending && !vacancy.data && (
           <div aria-busy="true" aria-label="Loading vacancy">
             {[0, 1].map((i) => (
               <CardSkeleton key={i} />
             ))}
           </div>
         )}
         {vacancy.isError && (
           <ErrorCard
             message={vacancy.error instanceof Error ? vacancy.error.message : "Could not load vacancy."}
             onRetry={() => void vacancy.refetch()}
           />
         )}
         {vacancy.data && (
           <div className="thin-scroll relative min-w-0 overflow-x-auto rounded-lg border border-gray-200 bg-white">
             <table className="w-full min-w-[720px] table-fixed border-collapse text-left">
               <thead>
                 <tr className="border-b border-gray-200 bg-gray-50">
                   <th scope="col" className="w-24 whitespace-nowrap px-3 py-2.5">
                     <span className="sr-only">Slot</span>
                   </th>
                   {days.map((d) => {
                     const { wd, num } = dayLabel(d.date);
                     const isToday = d.date === today;
                     return (
                       <th key={d.date} scope="col" className="whitespace-nowrap px-1 py-1 text-center">
                         <span
                           className={cn(
                             "block text-[11px] font-semibold uppercase tracking-wider",
                             isToday ? "text-primary-700" : "text-gray-500",
                           )}
                         >
                           {wd}
                         </span>
                         <span
                           className={cn(
                             "mx-auto mt-0.5 flex size-11 items-center justify-center font-technical text-2xl tabular-nums",
                             isToday ? "rounded-full bg-primary-50 text-primary-600" : "text-gray-900",
                           )}
                         >
                           {num}
                         </span>
                       </th>
                     );
                   })}
                 </tr>
               </thead>
               <tbody>
                 {TIME_SLOTS.map((slot) => (
                   <tr key={slot} className="border-b border-gray-100 last:border-0">
                     <th scope="row" className="whitespace-nowrap px-3 py-1.5 font-technical text-sm tabular-nums text-gray-500">
                       {formatTime12h(slot)}
                     </th>
                     {days.map((d) => {
                       const cell: VacancySlot | undefined = d.slots.find((s) => s.time === slot);
                       if (!cell) return <td key={d.date} className="px-1 py-1" />;
                       const closed = cell.state === "closed";
                       return (
                         <td key={d.date} className="px-1 py-1">
                           <button
                             type="button"
                             disabled={closed}
                             onClick={() => setSel({ date: d.date, time: slot })}
                             aria-label={`${formatDateLong(d.date)} ${formatTime12h(slot)}: ${cellText(cell)}`}
                             title={closed ? "Closed" : `${cell.left} of ${cell.capacity} seats left`}
                             className={cn(
                               "flex min-h-[44px] w-full cursor-pointer flex-col items-center justify-center rounded-lg border px-1 text-xs font-semibold tabular-nums transition-colors disabled:cursor-not-allowed",
                               cellPaint(cell.state),
                             )}
                           >
                             {cellText(cell)}
                           </button>
                         </td>
                       );
                     })}
                   </tr>
                 ))}
               </tbody>
             </table>
           </div>
         )}
       </div>

       <RemindersCard />
       <SlotDrawer sel={sel} onClose={() => setSel(null)} />
     </div>
   );
 }

