     max-width: 100%;
     padding: 0;
   }

   /* Avoid page breaks inside elements */
   .card, .table, .section {
     page-break-inside: avoid;
   }

   /* Show link URLs */
   a[href^="http"]::after {
     content: " (" attr(href) ")";
     font-size: 0.8em;
     color: #666;
   }

   /* Optimize tables */
   table {
     border-collapse: collapse;
     width: 100%;
   }

   th, td {
     border: 1px solid #ddd;
     padding: 8px;
   }

   /* Headers and footers */
