   }).formatToParts(now);
   const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
   return { ymd: `${get("year")}-${get("month")}-${get("day")}`, hour: Number(get("hour")) };
 }

 function addDays(ymd: string, days: number): string {
   const d = new Date(`${ymd}T00:00:00`);
   d.setDate(d.getDate() + days);
   return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
 }

 function toDate(ymd: string): Date | undefined {
   if (!/^\d{4}-\d{2}-\d{2}$/.test(ymd)) return undefined;
   return new Date(`${ymd}T00:00:00`);
 }

 function toYmd(d: Date): string {
   return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
 }

 function weekdayShort(ymd: string): string {
   return ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"][
     new Date(`${ymd}T00:00:00`).getDay()
   ] as string;
 }

 function monthDay(ymd: string): string {
   return new Date(`${ymd}T00:00:00`).toLocaleDateString("en-US", {
     month: "short",
     day: "numeric",
   });
 }

 function manilaClock(iso: string): string {
   return new Date(iso).toLocaleTimeString("en-PH", {
     hour: "numeric",
     minute: "2-digit",
     timeZone: "Asia/Manila",
   });
 }

 /** Day badge from its slots: closed beats full, full beats filling. */
 export function dayBadge(states: SlotState[]): string {
   if (states.length > 0 && states.every((s) => s === "closed")) return "Closed";
   if (states.length > 0 && states.every((s) => s === "closed" || s === "full")) return "Full";
   if (states.includes("low")) return "Filling";
   return "Open";
 }

 /**
  * Availability-first schedule picker: week strip with day states, earliest
  * shortcut, then time slots. Counts never reach the screen (privacy P1–P3) —
  * only open/filling/full/closed. A picked slot takes a 10-minute hold while
  * the guest types; the submit guard still owns the truth at the end.
  */
 export function SchedulePicker({
   date,
   time,
   allowSunday,
   hold,
   onHoldChange,
   mode,
   flexWindow,
   onModeChange,
   onFlexChange,
   onChange,
   errors,
 }: {
   date: string;
   time: string;
   allowSunday: boolean;
   hold: SlotHoldState | null;
   onHoldChange: (hold: SlotHoldState | null) => void;
   mode: ScheduleMode;
   flexWindow: FlexWindow;
   onModeChange: (mode: ScheduleMode) => void;
   onFlexChange: (window: FlexWindow) => void;
   onChange: (patch: { preferred_date?: string; preferred_time?: string }) => void;
   errors: { preferred_date?: string; preferred_time?: string };
 }) {
   const [calOpen, setCalOpen] = useState(false);
   const [showExact, setShowExact] = useState(false);
   const [holdFailed, setHoldFailed] = useState(false);
   const manila = useMemo(() => manilaParts(), []);
   const minDate = manila.hour < 12 ? manila.ymd : addDays(manila.ymd, 1);
   const maxDate = addDays(manila.ymd, 30);
   const createHold = useCreateHold();

   const avail = useSlotAvailability(minDate, maxDate);
   const dayMap = useMemo(
     () => new Map((avail.data?.days ?? []).map((d) => [d.date, d.slots])),
     [avail.data],
   );
   const live = !avail.isError;
   const slotState = (day: string, slot: string): SlotState | undefined =>
     live ? dayMap.get(day)?.find((s) => s.time === slot)?.state : undefined;

   const disabled: Matcher[] = useMemo(
     () => [
       { before: toDate(minDate) as Date },
       { after: toDate(maxDate) as Date },
       ...(allowSunday ? [] : [{ dayOfWeek: [0] }]),
     ],
     [minDate, maxDate, allowSunday],
   );

   const dateError = useMemo(() => {
     if (!date) return undefined;
     if (date < minDate) return "That date has passed — pick another day.";
     if (date > maxDate) return "Bookings open at most 30 days ahead.";
     const wd = new Date(`${date}T00:00:00`).getDay();
     if (wd === 0 && !allowSunday) return "We're closed on Sundays — pick another day.";
     return undefined;
     // eslint-disable-next-line react-hooks/exhaustive-deps
   }, [date, allowSunday]);

   const selected = toDate(date);
   const isToday = date === manila.ymd;
   const pastCutoff = (slot: string) =>
     isToday && Number(slot.slice(0, 2)) <= manila.hour;

   // One path holds the seat (exact mode only — windows lock nothing):
   // fresh pick, changed pick, or restored draft. Token must match the slot.
   const holdValid =
     mode === "exact" &&
     hold !== null && hold.date === date && hold.time === time && time !== "";
   useEffect(() => {
     if (mode !== "exact" || !date || !time || holdValid || createHold.isPending || holdFailed) return;
     setHoldFailed(false);
     createHold.mutate(
       { date, time },
       {
         onSuccess: (h: SlotHold) => {
           onHoldChange({ token: h.hold_token, reference: h.reference, expires: h.expires_at, date, time });
         },
         onError: () => {
           // Seat just filled (or network): drop the pick, states already refreshed.
           setHoldFailed(true);
           onHoldChange(null);
           onChange({ preferred_date: "", preferred_time: "" });
           void avail.refetch();
         },
       },
     );
     // eslint-disable-next-line react-hooks/exhaustive-deps
   }, [date, time, holdValid]);

   const pickSlot = (slot: string) => {
     setHoldFailed(false);
     onHoldChange(null);
     onModeChange("exact");
     onChange({ preferred_time: slot });
   };

   const pickDate = (ymd: string) => {
     setHoldFailed(false);
     onHoldChange(null);
     onChange({ preferred_date: ymd, preferred_time: "" });
   };

   const week = useMemo(() => Array.from({ length: 7 }, (_, i) => addDays(manila.ymd, i)), [manila]);
   // Sundays shut by house rule even when the feed is down — the strip must
   // never depend on the feed for what the rules already decide.
   const sundayShut = (ymd: string) =>
     new Date(`${ymd}T00:00:00`).getDay() === 0 && !allowSunday;
   const dayStates = useMemo(
     () =>
       week.map((ymd) => {
         if (!live) return undefined;
         const slots = dayMap.get(ymd);
         if (!slots) return undefined;
         return dayBadge(slots.map((s) => s.state));
       }),
     [week, live, dayMap],
   );

   const windowRoom = (ymd: string, w: FlexWindow): boolean => {
     const slots = dayMap.get(ymd);
     if (!slots) return false;
     return windowSlots(w).some((t) => {
       const st = slots.find((s) => s.time === t)?.state;
       return st === "open" || st === "low";
     });
   };

   const earliest = useMemo(() => {
     if (!live) return null;
     for (let i = 0; i <= 30; i += 1) {
       const ymd = addDays(manila.ymd, i);
       if (ymd < minDate || ymd > maxDate) continue;
       if (windowRoom(ymd, "morning")) return { date: ymd, window: "morning" as FlexWindow };
       if (windowRoom(ymd, "afternoon")) return { date: ymd, window: "afternoon" as FlexWindow };
     }
     return null;
     // eslint-disable-next-line react-hooks/exhaustive-deps
   }, [live, dayMap, manila, minDate, maxDate]);

   const fullDates = useMemo(() => {
     const out: Date[] = [];
     dayMap.forEach((slots, ymd) => {
       if (dayBadge(slots.map((s) => s.state)) === "Full") {
         const d = toDate(ymd);
         if (d) out.push(d);
       }
     });
     return out;
   }, [dayMap]);

   const daySlots = date ? (dayMap.get(date) ?? []) : [];
   const lowTimes = daySlots.filter((s) => s.state === "low").map((s) => formatTime12h(s.time));
   const slotOff = (slot: string) => {
     if (pastCutoff(slot)) return true;
     const st = date ? slotState(date, slot) : undefined;
     return st === "full" || st === "closed";
   };

   return (
     <div className="flex flex-col gap-4">
       <div>
         <Label id="slot-label">Pick a day *</Label>
         {avail.isPending && (
           <p className="mt-1.5 text-sm text-gray-600" role="status">Checking openings…</p>
         )}
         {avail.isError && (
           <p className="mt-1.5 text-sm text-gray-600">
             Live openings are unavailable right now — every open day is shown.
           </p>
         )}
         {earliest && !date && (
           <button
             type="button"
             onClick={() => {
               setHoldFailed(false);
               onHoldChange(null);
               onModeChange("window");
               onFlexChange(earliest.window);
               onChange({ preferred_date: earliest.date, preferred_time: "" });
             }}
             className="mt-2 flex min-h-[44px] cursor-pointer items-center justify-between gap-2 rounded-lg border border-primary-600 bg-primary-50 px-3 py-2 text-sm font-semibold text-primary-700 transition-colors hover:bg-primary-50"
           >
             <span>
               Earliest free: {weekdayShort(earliest.date)}, {monthDay(earliest.date)}{" "}
               {earliest.window === "morning" ? "morning" : "afternoon"}
             </span>
             <ArrowRight size={16} aria-hidden="true" className="shrink-0" />
           </button>
         )}
         <div className="mt-2 grid grid-cols-4 gap-2 sm:grid-cols-7" role="radiogroup" aria-labelledby="slot-label">
           {week.map((ymd, i) => {
             // Dots only while truly loading. Dead feed falls back to house
             // rules (matches the on-screen note); server badge wins live.
             const badge =
               dayStates[i] ??
               (avail.isPending
                 ? undefined
                 : ymd < minDate || sundayShut(ymd)
                   ? "Closed"
                   : "Open");
             const off = badge === "Full" || badge === "Closed";
             const picked = date === ymd;
             return (
               <button
                 key={ymd}
                 type="button"
                 role="radio"
                 aria-checked={picked}
                 disabled={avail.isPending || off}
                 onClick={() => pickDate(ymd)}
                 className={cn(
-                  "flex min-h-[64px] cursor-pointer flex-col items-center justify-center gap-0.5 rounded-lg border px-1 py-2 transition-colors disabled:cursor-not-allowed disabled:opacity-40",
+                  "flex min-h-[64px] cursor-pointer flex-col items-center justify-center gap-0.5 rounded-lg border px-1 py-2 transition-colors disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-40",
                   picked
                     ? "border-primary-600 bg-primary-50 text-primary-700"
                     : "border-gray-200 bg-white text-gray-700 hover:border-primary-300",
                 )}
               >
                 <span className="text-xs font-semibold">{weekdayShort(ymd)}</span>
                 <span className="font-technical text-base font-semibold tabular-nums">
                   {Number(ymd.slice(8, 10))}
                 </span>
                 <span className="text-[11px] text-gray-600">
                   {badge ?? "…"}
                 </span>
               </button>
             );
           })}
         </div>
         <div className="mt-2">
           <Popover open={calOpen} onOpenChange={setCalOpen}>
             <PopoverTrigger
               aria-label="Pick another date"
               className="inline-flex min-h-[44px] cursor-pointer items-center gap-2 rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm font-semibold text-gray-700 transition-colors hover:border-primary-300"
             >
               <CalendarDays size={18} className="shrink-0 text-gray-500" aria-hidden="true" />
               More dates
             </PopoverTrigger>
             <PopoverContent className="w-auto p-0" align="start">
               <Calendar
                 mode="single"
                 selected={selected}
                 disabled={disabled}
                 captionLayout="label"
                 startMonth={toDate(minDate)}
                 endMonth={toDate(maxDate)}
                 modifiers={{ full: fullDates }}
                 modifiersClassNames={{
                   selected:
                     "[&>button]:bg-primary-500 [&>button]:text-sm [&>button]:font-medium [&>button]:text-white [&>button:hover]:bg-primary-600 [&>button:hover]:text-white",
                   full: "[&>button]:text-gray-300 [&>button]:line-through [&>button]:hover:bg-transparent",
                 }}
                 onSelect={(d) => {
                   if (d) {
                     pickDate(toYmd(d));
                     setCalOpen(false);
                   }
                 }}
               />
             </PopoverContent>
           </Popover>
         </div>
         <FieldError message={errors.preferred_date ?? dateError} />
         {!allowSunday && (
           <p className="mt-1.5 text-xs text-gray-500">Closed on Sundays.</p>
         )}
       </div>
       <div>
         <Label id="window-label">Arrival window *</Label>
         <div className="mt-2 grid grid-cols-2 gap-2" role="radiogroup" aria-labelledby="window-label">
           {(["morning", "afternoon"] as FlexWindow[]).map((w) => {
             const sub = date
               ? dayBadge(
                   windowSlots(w).map(
                     (t) => dayMap.get(date)?.find((s) => s.time === t)?.state ?? "closed",
                   ),
                 )
               : null;
             const off = !date || sub === "Full" || sub === "Closed";
             const picked = mode === "window" && flexWindow === w;
             return (
               <button
                 key={w}
                 type="button"
                 role="radio"
                 aria-checked={picked}
                 disabled={off}
                 title={!date ? "Pick a day first" : undefined}
                 onClick={() => {
                   setHoldFailed(false);
                   onHoldChange(null);
                   onFlexChange(w);
                   onModeChange("window");
                 }}
                 className={cn(
-                  "flex min-h-[64px] cursor-pointer flex-col items-center justify-center gap-0.5 rounded-lg border px-2 py-2 transition-colors disabled:cursor-not-allowed disabled:opacity-40",
+                  "flex min-h-[64px] cursor-pointer flex-col items-center justify-center gap-0.5 rounded-lg border px-2 py-2 transition-colors disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-40",
                   picked
                     ? "border-primary-600 bg-primary-50 text-primary-700"
                     : "border-gray-200 bg-white text-gray-700 hover:border-primary-300",
                 )}
               >
                 <span className="text-sm font-semibold">
                   {w === "morning" ? "Morning" : "Afternoon"}
                 </span>
                 <span className="font-technical text-xs tabular-nums text-gray-600">
                   {w === "morning" ? "arrive 8–12" : "arrive 12–4"}
                 </span>
                 {sub && <span className="text-[11px] text-gray-600">{sub}</span>}
               </button>
             );
           })}
         </div>
         <button
           type="button"
           onClick={() => setShowExact((v) => !v)}
           aria-expanded={showExact}
           className="mt-2 inline-flex min-h-[44px] cursor-pointer items-center text-sm font-semibold text-primary-700 hover:text-primary-600"
         >
           {showExact ? "Back to windows" : "Need an exact hour? (estimates & follow-ups)"}
         </button>
         {showExact && (
           <>
         <Label id="time-label">
           {selected ? `Exact hour for ${formatDateLong(selected)} *` : "Exact hour *"}
         </Label>
         <div className="mt-2 grid grid-cols-3 gap-2" role="radiogroup" aria-labelledby="time-label">
           {TIME_SLOTS.map((slot) => (
             <button
               key={slot}
               type="button"
               role="radio"
               aria-checked={time === slot}
               disabled={!date || slotOff(slot)}
               title={
                 !date
                   ? "Pick a day first"
                   : slotOff(slot)
                     ? pastCutoff(slot)
                       ? "That hour already passed today"
                       : "That hour is fully booked"
                     : undefined
               }
               onClick={() => pickSlot(slot)}
               className={cn(
-                "min-h-[44px] cursor-pointer rounded-lg border px-2 font-technical text-sm font-medium transition-colors disabled:cursor-not-allowed disabled:opacity-40",
+                "min-h-[44px] cursor-pointer rounded-lg border px-2 font-technical text-sm font-medium transition-colors disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-40",
                 time === slot
                   ? "border-primary-600 bg-primary-50 text-primary-700"
                   : "border-gray-200 bg-white text-gray-700 hover:border-primary-300",
               )}
             >
               {formatTime12h(slot)}
             </button>
           ))}
         </div>
         <FieldError message={errors.preferred_time} />
         {lowTimes.length > 0 && mode === "exact" && (
           <p className="mt-1.5 text-sm text-gray-600">
             Filling fast: {lowTimes.join(", ")}.
           </p>
         )}
           </>
         )}
         {createHold.isPending && (
           <p className="mt-1.5 flex items-center gap-1.5 text-sm text-gray-600" role="status">
             <Loader2 size={16} aria-hidden="true" className="animate-spin" />
             Holding your seat…
           </p>
         )}
         {holdValid && hold && (
           <p className="mt-1.5 text-sm text-gray-600">
             Seat held for you ·{" "}
             <span className="font-technical">{hold.reference}</span> · until{" "}
             {manilaClock(hold.expires)}.
           </p>
         )}
         {holdFailed && (
           <p className="mt-1.5 text-sm text-error-600" role="alert">
             That slot just filled — pick another time.
           </p>
         )}
       </div>
     </div>
   );
 }

