 ### Stepper (Multi-Step Indicator)

 ```css
 .stepper {
   display: flex;
   align-items: center;
   justify-content: space-between;
   padding: 2rem 0;
   margin-bottom: 2rem;
 }

 .stepper-step {
   display: flex;
   flex-direction: column;
   align-items: center;
   flex: 1;
   position: relative;
 }

 .stepper-step:not(:last-child)::after {
   content: '';
   position: absolute;
   top: 1.5rem;
   left: calc(50% + 1.5rem);
   width: calc(100% - 3rem);
   height: 2px;
   background: var(--gray-200);
   z-index: -1;
 }

 .stepper-step.completed:not(:last-child)::after {
   background: var(--primary-400);
 }

 .stepper-circle {
   width: 3rem;
   height: 3rem;
   border-radius: 50%;
   background: var(--gray-200);
   color: var(--gray-500);
   font-family: var(--font-primary);
   font-size: 1.125rem;
   font-weight: 600;
   display: flex;
   align-items: center;
   justify-content: center;
   margin-bottom: 0.75rem;
   transition: all 200ms ease;
   position: relative;
   z-index: 1;
 }

 .stepper-step.active .stepper-circle {
   background: var(--primary-400);
   color: var(--white);
   box-shadow: 0 0 0 4px rgba(56, 182, 255, 0.2);
 }

 .stepper-step.completed .stepper-circle {
   background: var(--primary-400);
   color: var(--white);
 }

 .stepper-label {
   font-family: var(--font-primary);
   font-size: 0.875rem;
   color: var(--gray-600);
   text-align: center;
 }

 .stepper-step.active .stepper-label {
   color: var(--primary-600);
   font-weight: 600;
 }

 .stepper-step.completed .stepper-label {
   color: var(--gray-900);
   font-weight: 500;
 }

 /* Responsive Stepper */
 @media (max-width: 768px) {
   .stepper {
     flex-direction: column;
     align-items: stretch;
   }

   .stepper-step {
     flex-direction: row;
     align-items: center;
     justify-content: flex-start;
     gap: 1rem;
   }

   .stepper-step:not(:last-child)::after {
     top: calc(50% + 2rem);
     left: 1.5rem;
     width: 2px;
     height: calc(100% - 1rem);
   }

   .stepper-circle {
     margin-bottom: 0;
   }

   .stepper-label {
     text-align: left;
   }
 }
