 ### Print Styles

 ```css
 @media print {
   /* Hide non-essential elements */
   nav, .sidebar, .btn, .modal, .toast, footer {
     display: none !important;
   }

   /* Optimize for print */
   body {
     font-size: 12pt;
     line-height: 1.5;
     color: #000;
     background: #fff;
   }

   /* Expand containers */
   .container {
     max-width: 100%;
     padding: 0;
   }

   /* Avoid page breaks inside elements */
   .card, .table, .section {
     page-break-inside: avoid;
   }

   /* Show link URLs */
   a[href^="http"]::after {
     content: " (" attr(href) ")";
     font-size: 0.8em;
     color: #666;
   }

   /* Optimize tables */
   table {
     border-collapse: collapse;
     width: 100%;
   }

   th, td {
     border: 1px solid #ddd;
     padding: 8px;
   }

   /* Headers and footers */
   @page {
     margin: 2cm;
   }

   /* Remove shadows and borders */
   .card, .modal, .dropdown {
     box-shadow: none !important;
     border: 1px solid #ddd !important;
   }
 }
 ```

