     case "open":
-      return "border-teal-200 bg-teal-50 text-teal-900 hover:bg-teal-100";
+      return "border-teal-200 bg-teal-50 text-teal-900 hover:bg-teal-100 disabled:hover:bg-teal-50";
     case "low":
-      return "border-warning-200 bg-warning-50 text-warning-800 hover:bg-warning-100";
+      return "border-warning-200 bg-warning-50 text-warning-800 hover:bg-warning-100 disabled:hover:bg-warning-50";
     case "full":
-      return "border-slate-200 bg-slate-100 text-slate-600 hover:bg-slate-200";
+      return "border-slate-200 bg-slate-100 text-slate-600 hover:bg-slate-200 disabled:hover:bg-slate-100";
     default:
